import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Build from Source","description":"","frontmatter":{},"headers":[],"relativePath":"guide/source-installation.md","filePath":"guide/source-installation.md"}'),o={name:"guide/source-installation.md"};function r(n,e,l,d,p,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="build-from-source" tabindex="-1">Build from Source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from Source&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><a href="https://github.com/pphboy/piwork/blob/main/AGENTS.md#%E6%9E%84%E5%BB%BA%E4%B8%8E%E9%AA%8C%E8%AF%81" target="_blank" rel="noreferrer">Build the current source</a>, then run from the repository root. Released programs also work outside the checkout. Native programs support Linux x86-64 only.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-core</span></span></code></pre></div><p>Core includes administration, the workbench and first-time setup. Its only startup settings are <code>--ui-port</code> (17891), <code>--core-port</code> (17871), and <code>--data-dir</code> (piwork/server under the user configuration directory). <code>--help</code> and <code>--version</code> only display information. Ports must be distinct, within 1–65535 and different from internal RPC 7172. Relative data paths resolve from the working directory.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ui-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17991</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17971</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/piwork/custom/core</span></span></code></pre></div><p>Choose one startup command. Open the printed HTTP URL, create the administrator, then configure models and runtime in Admin Quick setup. On a headless server, open that address manually. Ctrl+C stops this installation’s managed Works while preserving data, history and desired state; restart with the same data path.</p><p>The Linux native client starts Desktop by default and connects to an existing Core. Select another Desktop port when the local Core UI already uses 17891. The client requires no Docker and does not start or stop Core.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:17871</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17901</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>Open <code>http://desktop.localhost:17901/</code> locally. Desktop shares user credentials with terminal commands but has its own default Core preference. Business commands select --core, PIWORK_CORE_URL, saved credentials, then the local default. Closing the browser or CLI does not stop Works. Windows browsers can also access the Linux Core UI.</p><p>One process serves two HTTP listeners: UI defaults to <code>0.0.0.0:17891</code>, Core to <code>0.0.0.0:17871</code>. Browsers use only UI, including files, events and <code>/services/&lt;workId&gt;/&lt;serviceId&gt;/&lt;port&gt;/</code>; the backend calls Core over fixed loopback HTTP. External Linux CLI connects directly to the server Core port. Change ports only with --ui-port/--core-port. UI accepts actual local IPv4 addresses, localhost, loopback and the machine hostname, validates Host, Origin and CSRF, and ignores Forwarded. Each address needs its own login. HTTP only; no HTTPS, custom domain or reverse proxy configuration. Internal Agent callbacks retain container-reachable mTLS on 7172. User Services publish no host ports. Model endpoints must be reachable from Work networks.</p><p><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/docker-delivery/spec.md" target="_blank" rel="noreferrer">Docker release builds</a></p>`,12)])])}const u=s(o,[["render",r]]);export{k as __pageData,u as default};
